    OPTIONS (user :'src_user', password :'src_password');
\endif
CREATE SCHEMA "src_cwp_ecr";
IMPORT FOREIGN SCHEMA public LIMIT TO (
    "ADGroupMembers",
    "ADGroups",
    "ActiveLanIds",
    "Files",
    "FolderInheritanceBreaks",
    "FolderPermissions",
    "Folder_Structure_Final_Analysis",
