    "Permissions",
    "PostgreSQL_PermissionMatrix_20260503",
    "PostgreSQL_SiteGroupPermission_20260503",
    "ScanProgress"
) FROM SERVER "srv_cwp_ecr" INTO "src_cwp_ecr";
